class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_up_to(n: int) -> int:
            if n == 0:
                return 0
            s_digits = list(map(int, str(n)))
            total_count = 0
            # Maximum possible sum of digits for n < 10^9 is 81 (for 999,999,999)
            # We'll go up to 82 to be safe
            for s in range(1, 82):
                # We'll run a digit DP for a fixed s
                # State: (pos, tight, leading_zeros, current_sum, current_prod_mod_s)
                # We use memoization with lru_cache
                from functools import lru_cache
                @lru_cache(maxsize=None)
                def dp(pos, tight, leading_zeros, current_sum, current_prod_mod_s):
                    if current_sum > s:
                        return 0
                    if pos == len(s_digits):
                        if leading_zeros:
                            return 0  # number 0 is not positive
                        if current_sum == s and current_prod_mod_s == 0:
                            return 1
                        return 0

                    limit = s_digits[pos] if tight else 9
                    res = 0
                    for d in range(limit + 1):
                        new_tight = tight and (d == limit)
                        new_leading_zeros = leading_zeros and (d == 0)

                        # Update sum
                        if leading_zeros and d == 0:
                            new_sum = current_sum  # remains 0
                        else:
                            new_sum = current_sum + d

                        # Update product modulo s
                        if leading_zeros and d == 0:
                            # Still in leading zeros, product remains 1 (identity) but we haven't started
                            new_prod_mod_s = 1
                        elif leading_zeros and d != 0:
                            # First non-zero digit
                            new_prod_mod_s = d % s
                        else:
                            # Not in leading zeros
                            new_prod_mod_s = (current_prod_mod_s * d) % s

                        # Prune if new_sum > s
                        if new_sum > s:
                            continue

                        res += dp(pos + 1, new_tight, new_leading_zeros, new_sum, new_prod_mod_s)

                    return res

                total_count += dp(0, True, True, 0, 1)

            return total_count

        return count_up_to(r) - count_up_to(l - 1)

import sys

# Increase recursion depth for deep trees to handle N up to 2*10^5
sys.setrecursionlimit(300000)

def solve():
    # Read all input from stdin efficiently
    input_data = sys.stdin.read().split()

    if not input_data:
        print(-1)
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
    except StopIteration:
        print(-1)
        return

    if N == 0:
        print(-1)
        return

    adj = [[] for _ in range(N + 1)]
    for _ in range(N - 1):
        try:
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)
        except StopIteration:
            break

    # DP arrays
    # dp[u][j] : max size of a valid alkane subgraph in u's subtree where u is included,
    #            u has exactly j edges to its children, and the subgraph contains at least one vertex of degree 4.
    # best[u][j]: max size of a valid subgraph in u's subtree where u is included,
    #             u has exactly j edges to its children, and the subgraph contains NO vertex of degree 4 (all degrees are 1).
    # j can be 0, 1, 3, 4.

    NEG_INF = -10**18

    dp = [[NEG_INF] * 5 for _ in range(N + 1)]
    best = [[NEG_INF] * 5 for _ in range(N + 1)]

    # Build traversal order (BFS/DFS) to process bottom-up
    parent = [0] * (N + 1)
    order = []
    stack = [1]
    visited = [False] * (N + 1)
    visited[1] = True

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    # Process in reverse order (bottom-up)
    for u in reversed(order):
        children = []
        for v in adj[u]:
            if v != parent[u]:
                children.append(v)

        if not children:
            # Leaf node in the original tree
            # It can be a leaf in the subgraph (degree 1 if connected to parent, 0 if root)
            # best[u][0] = 1 (just u, no degree 4 node)
            best[u][0] = 1
            continue

        leaf_opts = [] # Options where child is a leaf in the subgraph (contributes no degree 4 node)
        int_opts = []  # Options where child is an internal node in the subgraph (contributes a degree 4 node)

        for v in children:
            # If child v is a leaf in the subgraph, it must have 0 children in the subgraph.
            # We take best[v][0].
            if best[v][0] != NEG_INF:
                leaf_opts.append(best[v][0])

            # If child v is an internal node in the subgraph, it must have 3 children in the subgraph.
            # We take dp[v][3].
            if dp[v][3] != NEG_INF:
                int_opts.append(dp[v][3])

        # Sort descending to pick the largest contributions
        leaf_opts.sort(reverse=True)
        int_opts.sort(reverse=True)

        # Compute prefix sums for quick calculation
        prefix_leaf = [0] * (len(leaf_opts) + 1)
        for i in range(len(leaf_opts)):
            prefix_leaf[i+1] = prefix_leaf[i] + leaf_opts[i]

        prefix_int = [0] * (len(int_opts) + 1)
        for i in range(len(int_opts)):
            prefix_int[i+1] = prefix_int[i] + int_opts[i]

        # Calculate best[u][j] and dp[u][j] for j in {0, 1, 3, 4}
        for j in [0, 1, 3, 4]:
            if j > len(leaf_opts) + len(int_opts):
                continue

            # best[u][j]: select j children from leaf_opts only (no degree 4 nodes allowed in subtree)
            if j <= len(leaf_opts):
                val = prefix_leaf[j]
                if val != NEG_INF:
                    best[u][j] = val

            # dp[u][j]: select children such that at least one degree 4 node exists.
            # If j == 4, u itself has degree 4, so we can have 0 children from int_opts.
            # If j != 4, u does not have degree 4, so we must have at least 1 child from int_opts.

            max_val = NEG_INF

            if j == 4:
                limit_k = min(4, len(int_opts))
                for k in range(0, limit_k + 1):
                    rem = 4 - k
                    if rem <= len(leaf_opts):
                        current_val = prefix_int[k] + prefix_leaf[rem]
                        if current_val > max_val:
                            max_val = current_val
            else:
                limit_k = min(j, len(int_opts))
                for k in range(1, limit_k + 1):
                    rem = j - k
                    if rem <= len(leaf_opts):
                        current_val = prefix_int[k] + prefix_leaf[rem]
                        if current_val > max_val:
                            max_val = current_val

            if max_val != NEG_INF:
                dp[u][j] = max_val

        # Add 1 for u itself
        for j in [0, 1, 3, 4]:
            if best[u][j] != NEG_INF:
                best[u][j] += 1
            if dp[u][j] != NEG_INF:
                dp[u][j] += 1

    # Calculate final answer
    ans = -1

    for u in range(1, N + 1):
        # Case 1: u is the root of the alkane subgraph.
        # Degree of u in subgraph = j. Valid j in {1, 4}.
        for j in [1, 4]:
            if dp[u][j] != NEG_INF:
                if dp[u][j] > ans:
                    ans = dp[u][j]

        # Case 2: u is an internal node connected to its parent.
        # Degree of u in subgraph = j + 1. Valid j+1 in {1, 4} => j in {0, 3}.
        for j in [0, 3]:
            if dp[u][j] != NEG_INF:
                if dp[u][j] > ans:
                    ans = dp[u][j]

    print(ans)

