import sys
from collections import deque

# Increase recursion depth just in case, though we use iterative BFS
sys.setrecursionlimit(200005)

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        M = int(next(iterator))
        S = int(next(iterator))
        T = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(N + 1)]
    degree = [0] * (N + 1)

    for _ in range(M):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)
        degree[u] += 1
        degree[v] += 1

    # BFS to find shortest distance from S to T
    dist = [-1] * (N + 1)
    dist[S] = 0
    queue = deque([S])

    while queue:
        u = queue.popleft()
        if u == T:
            break
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)

    d_st = dist[T]

    # Count nodes with degree 1
    count_deg1 = 0
    for i in range(1, N + 1):
        if degree[i] == 1:
            count_deg1 += 1

    if d_st == 1:
        # S and T are adjacent
        if degree[S] == 1 and degree[T] == 1:
            print(-1)
        else:
            print(3)
    else:
        # S and T are not adjacent
        if degree[S] == 1 and degree[T] == 1:
            # Check if the graph is a simple path between S and T
            # This happens if it's a tree (M = N-1) and only S and T have degree 1
            if M == N - 1 and count_deg1 == 2:
                print(-1)
            else:
                print(2 * d_st)
        else:
            print(2 * d_st)

if __name__ == '__main__':
    solve()

