from collections import defaultdict

class Solution:
    def longestSpecialPath(self, edges: List[List[int]], nums: List[int]) -> List[int]:
        n = len(nums)
        graph = defaultdict(list)
        for u, v, length in edges:
            graph[u].append((v, length))
            graph[v].append((u, length))

        max_length = 0
        min_nodes = float('inf')

        seen = set()

        def dfs(node, current_length, current_nodes, path_set):
            nonlocal max_length, min_nodes

            if nums[node] in path_set:
                return

            path_set.add(nums[node])

            new_length = current_length
            new_nodes = current_nodes + 1

            if new_length > max_length:
                max_length = new_length
                min_nodes = new_nodes
            elif new_length == max_length:
                if new_nodes < min_nodes:
                    min_nodes = new_nodes

            for child, length in graph[node]:
                if child == -1:
                    continue
                # Check if child is parent (to avoid going back up)
                # But since we are building the tree from root, we need to track parent
                pass

            # We need to restructure to avoid parent issues. Instead, build a directed tree from root.
            pass

        # Rebuild the tree as a directed graph from root
        tree = defaultdict(list)
        visited = [False] * n
        queue = [0]
        visited[0] = True
        while queue:
            u = queue.pop(0)
            for v, length in graph[u]:
                if not visited[v]:
                    visited[v] = True
                    tree[u].append((v, length))
                    queue.append(v)

        def dfs_detailed(node, current_length, current_nodes, path_set):
            nonlocal max_length, min_nodes

            if nums[node] in path_set:
                return

            path_set.add(nums[node])
            new_length = current_length
            new_nodes = current_nodes + 1

            if new_length > max_length:
                max_length = new_length
                min_nodes = new_nodes
            elif new_length == max_length:
                if new_nodes < min_nodes:
                    min_nodes = new_nodes

            for child, length in tree[node]:
                dfs_detailed(child, current_length + length, new_nodes, path_set)

            path_set.remove(nums[node])

        dfs_detailed(0, 0, 0, set())

        return [max_length, min_nodes]

class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        if not s:
            return 0

        # Get the lengths of consecutive runs
        runs = []
        current_run = 1
        for i in range(1, len(s)):
            if s[i] == s[i-1]:
                current_run += 1
            else:
                runs.append(current_run)
                current_run = 1
        runs.append(current_run)

        # Iterate over possible target maximum run lengths x from 1 to n
        n = len(s)
        for x in range(1, n + 1):
            total_flips = 0
            for L in runs:
                # Number of flips needed for a run of length L to have max segment length x
                # is ceil(L/(x+1)) - 1
                flips = (L + x) // (x + 1) - 1
                total_flips += flips
                if total_flips > numOps:
                    break
            if total_flips <= numOps:
                return x

        return n
